      ET_CHECK_OR_RETURN_ERROR(
          qnn_graph_ptr->EnsureTensorInQnnGraph(graph_name, tensor_wrapper) ==
              Error::Ok,

    error = qnn_graph_ptr->GraphAddNode(graph_name, op_wrapper->GetOpConfig());
